/bin/bash -lc "python - <<'PY'
import urllib.request, xml.etree.ElementTree as ET
for prefix in ['resources/hgdp_1kg/', 'resources/hgdp_1kg_v2/', 'resources/gnomad/hgdp_1kg/', 'resources/hgdp_tgp/', 'resources/hgdp1kgp/']:
    u='https://gnomad-public-us-east-1.s3.amazonaws.com/?list-type=2&prefix='+prefix+'&max-keys=200'
    root=ET.fromstring(urllib.request.urlopen(u, timeout=20).read())
    ns={'s':'http://s3.amazonaws.com/doc/2006-03-01/'}
    keys=[c.findtext('s:Key', namespaces=ns) for c in root.findall('s:Contents', ns)]
    print(prefix, len(keys))
    for k in keys[:20]: print(' ',k)
PY"

/bin/bash -lc "python - <<'PY'
import urllib.request
candidates=[
 'https://raw.githubusercontent.com/broadinstitute/gnomad_methods/main/gnomad/resources/grch38/gnomad.py',
 'https://raw.githubusercontent.com/broadinstitute/gnomad_qc/main/gnomad_qc/v3/resources/basics.py',
 'https://raw.githubusercontent.com/broadinstitute/gnomad_qc/main/gnomad_qc/v3/resources/annotations.py',
 'https://raw.githubusercontent.com/broadinstitute/gnomad_qc/main/gnomad_qc/v4/resources/sample_qc.py',
]
for u in candidates:
    try:
        txt=urllib.request.urlopen(u, timeout=15).read().decode('utf-8','ignore')
        print('\\nURL',u,'len',len(txt))
        for line in txt.splitlines():
            if 'hgdp' in line.lower() or '1kg' in line.lower():
                print(line[:300])
    except Exception as e: print('ERR',u,e)
PY"

